html:
{% set c = get_print_context(doc) %}
<style>
.nc-page { font-size: 12px; color: #1f272e; }
.nc-wm-top { text-align: center; font-weight: 700; font-size: 20px; color: #c0392b; letter-spacing: 4px; }
.nc-wm-bg { position: fixed; top: 40%; left: 8%; width: 90%; text-align: center; font-size: 110px; font-weight: 700;
	color: rgba(192, 57, 43, 0.12); transform: rotate(-30deg); z-index: -1; }
.nc-title { text-align: center; font-size: 18px; font-weight: 700; margin: 6px 0 2px; }
.nc-sub { text-align: center; margin-bottom: 8px; }
.nc-page table { width: 100%; border-collapse: collapse; margin: 6px 0 10px; }
.nc-page th, .nc-page td { border: 1px solid #888; padding: 3px 5px; vertical-align: top; text-align: left; }
.nc-page h4 { margin: 12px 0 4px; font-size: 13px; }
.nc-sign td { height: 70px; text-align: center; }
</style>
<div class="nc-page">
{% if c.is_draft %}
<div class="nc-wm-top">{{ c.watermark }}</div>
<div class="nc-wm-bg">{{ c.watermark }}</div>
{% endif %}
<div class="nc-title">{{ c.title }}</div>
<div class="nc-sub">{{ c.service_name }}{% if c.service_code %} ({{ c.service_code }}){% endif %}<br>Khoa chủ trì: {{ c.department }}</div>
{% if c.status_note %}<div class="nc-sub"><b>{{ c.status_note }}</b></div>{% endif %}
<table>
<tr><th>Số hiệu</th><td>{{ c.number }}</td><th>Phiên bản</th><td>{{ c.version }}</td></tr>
<tr><th>Số quyết định</th><td>{{ c.decision_no }}</td><th>Ngày hiệu lực</th><td>{{ c.effective_date }}</td></tr>
<tr><th>Trạng thái</th><td colspan="3">{{ c.state }}</td></tr>
</table>
{% for sec in c.sections %}
<h4>{{ loop.index }}. {{ sec.heading }}</h4>
{% if sec.is_steps %}
{% for ph in c.phases %}
<b>{{ ph.phase }}</b>
<table>
<tr><th>Mã</th><th>Tên bước</th><th>Mô tả</th><th>Phút</th></tr>
{% for s in ph.steps %}
<tr><td>{{ s.step_id }}</td><td>{{ s.title }}</td><td>{{ s.description }}</td><td>{{ s.minutes if s.minutes is not none else "" }}</td></tr>
{% endfor %}
</table>
{% endfor %}
{% if c.resources %}
<b>Nguồn lực</b>
<table>
<tr><th>Bước</th><th>Nguồn lực</th><th>Số lượng</th><th>Đơn vị</th></tr>
{% for r in c.resources %}
<tr><td>{{ r.step_id }}</td><td>{{ r.resource_text or r.linked_name or "" }}</td><td>{{ r.quantity if r.quantity is not none else "" }}</td><td>{{ r.uom or "" }}</td></tr>
{% endfor %}
</table>
{% endif %}
{% else %}
<div>{{ sec.text | safe }}</div>
{% endif %}
{% endfor %}
<h4>Chữ ký</h4>
<table class="nc-sign">
<tr>{% for s in c.signatures %}<th>{{ s.label }}</th>{% endfor %}</tr>
<tr>{% for s in c.signatures %}<td>{{ s.user }}<br>{{ s.date }}</td>{% endfor %}</tr>
</table>
</div>
